using System.Collections.Generic;
using UnityEngine;

public sealed partial class DefenseGame {
 sealed class CivilUnit {public CivilizationModel.War war;public bool enemy;public int index;public OrbitDemo.State state;public Transform root;public float fire;public float HP {get{return enemy?war.hostile[index]:war.friendly[index];}set{if(enemy)war.hostile[index]=value;else war.friendly[index]=value;}}}
 sealed class CivilBolt {public OrbitDemo.State state;public Vector3 previous;public LineRenderer view;public CivilUnit owner;public float age;}
 readonly List<CivilUnit> civilUnits=new List<CivilUnit>();readonly List<CivilBolt> civilBolts=new List<CivilBolt>();
 GalacticPoint CivilBattleGlobal(CivilizationModel.War w){var port=ports[w.target];Vector3 direction=w.source==w.target?new Vector3(.14f,.98f,.1f).normalized:(ports[w.source].global-port.global).normalized;return port.global+direction*(port.radius+2100);}
 bool CivilBattleLoaded(CivilizationModel.War w){return WorldDistance(CivilBattleGlobal(w),GlobalPosition)<6500;}
 void CivilWarShift(Vector3 shift){foreach(var u in civilUnits){MoveState(ref u.state,shift);u.root.position-=shift;}foreach(var b in civilBolts){MoveState(ref b.state,shift);b.previous-=shift;for(int i=0;i<b.view.positionCount;i++)b.view.SetPosition(i,b.view.GetPosition(i)-shift);}}
 void CivilWarTick(float dt){
  for(int i=civilUnits.Count-1;i>=0;i--){var u=civilUnits[i];if(u.war.resolved||u.HP<=0||!CivilBattleLoaded(u.war)){if(u.HP<=0)CinematicPresentation.Impact(u.root.position,u.enemy?new Color(1,.28f,.1f):Color.cyan);Destroy(u.root.gameObject);civilUnits.RemoveAt(i);}}
  foreach(var w in civilization.wars){if(voyager!=null&&!w.scaled){for(int h=0;h<w.hostile.Length;h++)w.hostile[h]*=ThreatHealth;w.scaled=true;}if(w.resolved||w.travel>0||!CivilBattleLoaded(w))continue;Vector3 center=CivilBattleGlobal(w)-OriginGlobal;var planet=expedition.Nearest(center);Vector3 up=(center-planet.body.P).normalized,tangent=PlanetExpedition.SurfaceTangent(up,Vector3.right),side=Vector3.Cross(up,tangent);
   for(int team=0;team<2;team++){float[] hp=team==0?w.friendly:w.hostile;for(int i=0;i<hp.Length;i++){bool enemy=team==1;if(hp[i]<=0||civilUnits.Exists(u=>u.war==w&&u.index==i&&u.enemy==enemy))continue;var material=enemy?frontierArt.violet:frontierArt.porcelain;var root=enemy&&w.enemy==2?frontierArt.AlienWarship(null,w.flagship&&i==0):frontierArt.Hull(null,enemy?3:2,material);root.name=(enemy?civilization.factions[w.enemy].name:"PLAYER FLEET")+" / native ship "+i;root.localScale=Vector3.one*(w.flagship&&enemy&&i==0?9:4);if(w.flagship&&enemy&&i==0)root.name="THE ALIEN ARK / FLAGSHIP";Vector3 p=center+tangent*((enemy?1:-1)*100)+side*((i-(hp.Length-1)*.5f)*44)+up*20;civilUnits.Add(new CivilUnit{war=w,index=i,enemy=enemy,root=root,state=Make(p,Vector3.zero),fire=.3f+i*.2f});}}
   w.nativeClock+=dt;if(w.nativeClock>95)civilization.StrategicCombat(w,dt);civilization.Resolve(w);
  }
  foreach(var u in civilUnits){if(u.HP<=0)continue;Vector3 center=CivilBattleGlobal(u.war)-OriginGlobal;var planet=expedition.Nearest(center);Vector3 up=(center-planet.body.P).normalized,t=PlanetExpedition.SurfaceTangent(up,Vector3.right),s=Vector3.Cross(up,t);float age=civilization.seconds;
   Vector3 goal=center+t*((u.enemy?1:-1)*115+Mathf.Sin(age*.14f+u.index)*30)+s*((u.index-1)*48+Mathf.Sin(age*.2f+u.index)*20)+up*(24+Mathf.Sin(age*.17f+u.index)*16);
   if(voyager!=null){int role=u.index%3;float hpMax=u.enemy?(u.war.flagship&&u.index==0?1200:110*ThreatHealth):145;if(u.HP<hpMax*.25f)goal+=t*(u.enemy?240:-240);else if(role==1)goal+=s*Mathf.Sin(age*.10f+u.index)*125;else if(role==0)goal+=t*(u.enemy?110:-110);}
    Vector3 desired=Vector3.ClampMagnitude((goal-Pos(u.state))*.8f,24);Vector3 force=Vector3.ClampMagnitude((desired-Vel(u.state))*3-Gravity(Pos(u.state)),120);
   for(float elapsed=0;elapsed<dt-.00001f;elapsed+=.01f)Step(ref u.state,force,Mathf.Min(.01f,dt-elapsed));u.root.position=Pos(u.state);var targets=civilUnits.FindAll(v=>v.war==u.war&&v.enemy!=u.enemy&&v.HP>0);if(targets.Count==0)continue;var target=targets[(u.index+Mathf.FloorToInt(age*.2f))%targets.Count];Vector3 delta=Pos(target.state)-Pos(u.state);u.root.rotation=Quaternion.Slerp(u.root.rotation,Quaternion.LookRotation(delta,up),dt*3);u.fire-=dt;
   if(u.fire<=0&&civilBolts.Count<72){u.fire=(1.3f+u.index*.07f)/(voyager==null?1:1+voyager.chapter*.025f);if(u.war.flagship&&u.enemy&&u.index==0)u.fire=u.HP<600?.45f:.8f;float flight=delta.magnitude/140;Vector3 aim=Pos(target.state)+Vel(target.state)*flight-Gravity(Pos(target.state))*.5f*flight*flight;if(voyager!=null&&u.enemy&&Vector3.Distance(Pos(player),Pos(u.state))<320&&((Mathf.FloorToInt(age)+u.index)%3==0||u.war.flagship&&u.index==0)){Vector3 d=Pos(player)-Pos(u.state);float lead=d.magnitude/140;aim=Pos(player)+Vel(player)*lead-Gravity(Pos(player))*.5f*lead*lead;}var bolt=new CivilBolt{owner=u,state=Make(Pos(u.state)+delta.normalized*10,(aim-Pos(u.state)).normalized*140+Vel(u.state)),previous=Pos(u.state)};bolt.view=new GameObject("Fleet / native plasma bolt").AddComponent<LineRenderer>();bolt.view.positionCount=2;bolt.view.widthMultiplier=.65f;bolt.view.sharedMaterial=u.enemy?frontierArt.beamViolet:frontierArt.beamCyan;bolt.view.SetPositions(new[]{Pos(u.state),Pos(u.state)});civilBolts.Add(bolt);}
  }
  for(int i=civilBolts.Count-1;i>=0;i--){var b=civilBolts[i];b.age+=dt;Vector3 before=Pos(b.state);for(float elapsed=0;elapsed<dt-.00001f;elapsed+=.01f)PlanetExpedition.StepMode(ref b.state,Vector3.zero,Mathf.Min(.01f,dt-elapsed),1);Vector3 after=Pos(b.state);bool hit=false;foreach(var target in civilUnits)if(target.enemy!=b.owner.enemy&&target.war==b.owner.war&&target.HP>0&&SegmentDistance(Pos(target.state),before,after)<(target.war.flagship&&target.enemy&&target.index==0?20:8)){target.HP=Mathf.Max(0,target.HP-24);CinematicPresentation.Impact(after,b.owner.enemy?new Color(.9f,.1f,1):Color.cyan);hit=true;break;}
   if(b.owner.enemy&&SegmentDistance(Pos(player),before,after)<1.2f){GroundDamage(9);hit=true;}b.view.SetPositions(new[]{after,after-Vel(b.state).normalized*10});if(hit||b.age>4||b.state.captured!=0){Destroy(b.view.gameObject);civilBolts.RemoveAt(i);}}
  foreach(var w in civilization.wars)civilization.Resolve(w);
 }
 bool CivilHit(Vector3 before,Vector3 after,bool playerShot,float damage=1){if(civilization==null||!playerShot)return false;foreach(var u in civilUnits)if(u.enemy&&u.HP>0&&SegmentDistance(Pos(u.state),before,after)<(u.war.flagship&&u.index==0?20:8)){u.HP=Mathf.Max(0,u.HP-48*damage);CinematicPresentation.Impact(after,new Color(1,.45f,.08f));if(u.HP<=0){u.war.playerKills++;if(voyager!=null)voyager.nativeKills++;GroundReward(120,2);Notice("ORBITAL WAR / hostile warship destroyed / +120 / +2 parts");}civilization.Resolve(u.war);return true;}return false;}
 void DrawCivilWar(){if(civilization==null||civilOpen||paused||GroundActive)return;foreach(var u in civilUnits){Vector3 p=cam.WorldToScreenPoint(u.root.position);if(p.z<=0)continue;float x=p.x/Screen.width*1600,y=1000-p.y/Screen.height*1000;if(x<80||x>1500||y<185||y>770)continue;GUI.color=u.enemy?new Color(1,.3f,.6f):new Color(.25f,1,.9f);GUI.DrawTexture(new Rect(x-35,y-16,70*Mathf.Clamp01(u.HP/(u.enemy?(u.war.flagship&&u.index==0?1200:110*ThreatHealth):145)),3),Texture2D.whiteTexture);GUI.color=Color.white;GUI.Label(new Rect(x-50,y-42,200,25),u.war.flagship&&u.enemy&&u.index==0?"ALIEN ARK / FLAGSHIP":u.enemy?"HOSTILE FLEET":"ALLIED FLEET",small);}}
}
